/**
 * Single source of truth for the free tools directory. Data-only (no JSX) so it
 * can be imported by the sitemap, the /tools hub, and nav without pulling in
 * client code. Icons are mapped from `icon` keys at the render site.
 */

export type ToolCategory = "Network" | "Developer" | "Security";

export type Tool = {
  slug: string; // path under /tools
  name: string;
  tagline: string;
  category: ToolCategory;
  icon: string; // key into the icon map in the hub page
  serverSide: boolean; // true = hits an /api/tools route; false = runs in-browser
};

export const TOOLS: Tool[] = [
  // Listed first deliberately: it is the only tool with real commercial intent —
  // a visitor naming a business is a visitor about to buy a domain — so it leads
  // the hub and every other tool cross-links back to it.
  {
    slug: "domain-generator",
    name: "AI Domain Name Generator",
    tagline: "Describe your idea, get brandable names that are actually available.",
    category: "Network",
    icon: "spark",
    serverSide: true,
  },
  {
    slug: "whois",
    name: "WHOIS Lookup",
    tagline: "Registrar, dates & nameservers for any domain.",
    category: "Network",
    icon: "globe",
    serverSide: true,
  },
  {
    slug: "dns-lookup",
    name: "DNS Lookup",
    tagline: "Resolve A, AAAA, MX, TXT, NS, CNAME and SOA records.",
    category: "Network",
    icon: "network",
    serverSide: true,
  },
  {
    slug: "port-checker",
    name: "Port Checker",
    tagline: "Test whether a TCP port is open, with latency.",
    category: "Network",
    icon: "server",
    serverSide: true,
  },
  {
    slug: "ssl-checker",
    name: "SSL Certificate Checker",
    tagline: "Issuer, validity, expiry and chain for any HTTPS host.",
    category: "Network",
    icon: "lock",
    serverSide: true,
  },
  {
    slug: "http-headers",
    name: "HTTP Header Checker",
    tagline: "Inspect status code and response headers for a URL.",
    category: "Network",
    icon: "code",
    serverSide: true,
  },
  {
    slug: "my-ip",
    name: "What Is My IP",
    tagline: "See your public IP address and reverse DNS.",
    category: "Network",
    icon: "gauge",
    serverSide: true,
  },
  {
    slug: "password-generator",
    name: "Password Generator",
    tagline: "Strong random passwords, generated in your browser.",
    category: "Security",
    icon: "shield",
    serverSide: false,
  },
  {
    slug: "hash-generator",
    name: "Hash Generator",
    tagline: "SHA-1, SHA-256, SHA-384 and SHA-512 hashes.",
    category: "Security",
    icon: "lock",
    serverSide: false,
  },
  {
    slug: "subnet-calculator",
    name: "Subnet / CIDR Calculator",
    tagline: "Network, broadcast, host range and counts from a CIDR.",
    category: "Network",
    icon: "network",
    serverSide: false,
  },
  {
    slug: "base64",
    name: "Base64 Encode / Decode",
    tagline: "Convert text to and from Base64, UTF-8 safe.",
    category: "Developer",
    icon: "terminal",
    serverSide: false,
  },
  {
    slug: "json-formatter",
    name: "JSON Formatter & Validator",
    tagline: "Beautify, minify and validate JSON instantly.",
    category: "Developer",
    icon: "code",
    serverSide: false,
  },
  {
    slug: "uuid-generator",
    name: "UUID Generator",
    tagline: "Generate v4 UUIDs in bulk, copy with one click.",
    category: "Developer",
    icon: "spark",
    serverSide: false,
  },
];

export const TOOL_SLUGS = TOOLS.map((t) => t.slug);

export function toolsByCategory(): Record<ToolCategory, Tool[]> {
  const out: Record<ToolCategory, Tool[]> = { Network: [], Developer: [], Security: [] };
  for (const t of TOOLS) out[t.category].push(t);
  return out;
}

/** Small related-tools helper for a given slug (same category, excluding self). */
export function relatedTools(slug: string, limit = 4): { label: string; href: string }[] {
  const self = TOOLS.find((t) => t.slug === slug);
  if (!self) return [];
  const same = TOOLS.filter((t) => t.slug !== slug && t.category === self.category);
  const rest = TOOLS.filter((t) => t.slug !== slug && t.category !== self.category);
  return [...same, ...rest].slice(0, limit).map((t) => ({ label: t.name, href: `/tools/${t.slug}` }));
}
