  IconGlobe,
  IconNetwork,
  IconServer,
  IconLock,
  IconCode,
  IconGauge,
  IconShield,
  IconTerminal,
  IconSpark,
  IconArrow,
} from "@/components/marketing/icons";

const APP_URL = process.env.APP_URL ?? "https://nxeon.cloud";

