const ICONS: Record<string, (p: { size?: number }) => React.ReactNode> = {
  globe: IconGlobe,
  network: IconNetwork,
  server: IconServer,
  lock: IconLock,
  code: IconCode,
  gauge: IconGauge,
  shield: IconShield,
  terminal: IconTerminal,
  spark: IconSpark,
};

const CATEGORY_BLURB: Record<ToolCategory, string> = {
  Network: "Diagnose domains, DNS, ports and certificates — the checks you run before and after every deploy.",
  Developer: "Everyday encode/format/generate utilities that run entirely in your browser.",
  Security: "Generate strong secrets and hashes locally — nothing is ever sent to a server.",
