}

export default function ToolsHubPage() {
  const grouped = toolsByCategory();
  const order: ToolCategory[] = ["Network", "Developer", "Security"];

  const itemList = {
    "@context": "https://schema.org",
    "@type": "ItemList",
    name: "Free networking and developer tools",
    itemListElement: TOOLS.map((t, i) => ({
      "@type": "ListItem",
      position: i + 1,
      name: t.name,
      url: `${APP_URL}/tools/${t.slug}`,
    })),
  };

  return (
    <>
      <script type="application/ld+json" dangerouslySetInnerHTML={{ __html: JSON.stringify(itemList) }} />

      <PageHero
        eyebrow="Free tools"
        title="Networking & developer tools,"
        highlight="free forever"
        sub={`A growing suite of ${TOOLS.length} genuinely useful utilities — WHOIS, DNS, port & SSL checks, HTTP headers, password and hash generators, subnet math and more. No signup, no limits, no tracking.`}
        primary={{ label: "Deploy a VPS", href: "/vps" }}
        secondary={{ label: "See pricing", href: "/pricing" }}
      />

      <Section tone="panel" size="sm">
        <div className="grid gap-8 text-center sm:grid-cols-3">
          <div>
            <p className="text-3xl font-bold text-white">{TOOLS.length}</p>
            <p className="mt-1 text-sm text-slate-400">Free tools</p>
          </div>
          <div>
            <p className="text-3xl font-bold text-white">$0</p>
            <p className="mt-1 text-sm text-slate-400">Forever — no account needed</p>
          </div>
          <div>
            <p className="text-3xl font-bold text-white">6</p>
            <p className="mt-1 text-sm text-slate-400">Run 100% in your browser</p>
          </div>
        </div>
      </Section>

      {order.map((cat, ci) => (
        <Section key={cat} size="lg" tone={ci % 2 === 1 ? "panel" : "base"}>
          <SectionTitle eyebrow={`${cat} tools`} title={`${cat} tools`} sub={CATEGORY_BLURB[cat]} align="left" />
          <div className="mt-10 grid gap-5 sm:grid-cols-2 lg:grid-cols-3">
            {grouped[cat].map((t, i) => (
              <ToolCard key={t.slug} tool={t} delay={(i % 3) * 60} />
            ))}
          </div>
        </Section>
      ))}

      <Section tone="deep" size="lg">
        <CtaBand />
      </Section>
    </>
  );
}

