import type { Metadata } from "next";
import { ToolShell, FaqJsonLd, type ToolFaq } from "@/components/marketing/ToolShell";
import { PortCheckerTool } from "@/components/marketing/tools/PortCheckerTool";
import { relatedTools } from "@/lib/tools/catalog";

export const metadata: Metadata = {
  title: "Free Open Port Checker — Test TCP Ports Online",
  description:
    "Free online port checker. Test whether a TCP port is open on any host or IP from the public internet, with connection latency. Verify SSH, HTTP, HTTPS, database and custom ports.",
  alternates: { canonical: "/tools/port-checker" },
};

const faq: ToolFaq[] = [
  {
    q: "What does 'open' vs 'closed / filtered' mean?",
    a: "Open means our server completed a TCP handshake with that port — something is listening and reachable. Closed/filtered means the connection was refused or timed out, which can be a firewall dropping the packet, no service listening, or the host being unreachable.",
  },
  {
    q: "Why is my port open locally but closed here?",
    a: "This tool tests from the public internet inward. A port can be listening on the server yet blocked by a cloud firewall, security group, or the host's own firewall (ufw/iptables). If it's closed here but works locally, check those layers.",
  },
  {
    q: "Can I check any port number?",
    a: "Yes, any port from 1 to 65535. Use the quick presets for common services like SSH (22), HTTP (80), HTTPS (443) and databases, or type your own.",
  },
  {
    q: "Do you scan private or internal addresses?",
    a: "No. For security we resolve the host and refuse private, loopback, link-local and reserved ranges, so the tool can't be used to probe internal networks.",
  },
];

export default function Page() {
  return (
    <>
      <FaqJsonLd faq={faq} />
      <ToolShell
        category="Network tool"
        title="Open Port Checker"
        description="Test whether a TCP port is reachable on any public host or IP address, and see how long the connection took."
        about={[
          {
            heading: "What is a port checker?",
            body: (
              <p>
                Network services listen on numbered TCP ports — web servers on 80 and 443, SSH on 22,
                databases on ports like 3306 and 5432. A port checker attempts a TCP connection to a
                given host and port from the outside and tells you whether it succeeded. It's the quickest
                way to confirm a service is exposed and that no firewall is silently blocking it.
              </p>
            ),
          },
          {
            heading: "Common ports to test",
            body: (
              <ul className="list-disc space-y-1 pl-5">
                <li><b>22</b> — SSH remote access</li>
                <li><b>80 / 443</b> — HTTP and HTTPS web traffic</li>
                <li><b>25 / 587 / 465</b> — outbound and submission SMTP mail</li>
                <li><b>3306 / 5432</b> — MySQL and PostgreSQL databases</li>
                <li><b>6379 / 27017</b> — Redis and MongoDB</li>
              </ul>
            ),
          },
        ]}
        steps={[
          "Enter a hostname or IP address.",
          "Type a port number, or tap one of the common-service presets.",
          "Click Check to attempt a TCP connection from our server.",
          "Read the open/closed result and the measured connection latency.",
        ]}
        faq={faq}
        related={relatedTools("port-checker")}
      >
        <PortCheckerTool />
      </ToolShell>
    </>
  );
}
=== api/tools/port-checker ===
import { NextResponse } from "next/server";
import net from "node:net";
import { jsonError } from "@/lib/tools/api";
import { toolRateLimitByIp, trustedClientIp } from "@/app/api/_lib/client-ip";
import { checkRateLimit } from "@/lib/rate-limit";
import { extractHost, resolvePublicHost, BlockedHostError } from "@/lib/tools/net-guard";

export const runtime = "nodejs";
export const dynamic = "force-dynamic";

/**
 * TCP port checker — opens a TCP connection to host:port and reports open/closed
 * plus connect latency. The host is SSRF-guarded (resolved to a public IP; private
 * / loopback / reserved targets are rejected) and we connect to the vetted IP,
 * never re-resolving. Port must be 1-65535. Timeout ≤5s, rate-limited per IP.
 */

const TIMEOUT_MS = 5000;

const COMMON: Record<number, string> = {
  20: "FTP-DATA", 21: "FTP", 22: "SSH", 23: "Telnet", 25: "SMTP", 53: "DNS",
  80: "HTTP", 110: "POP3", 143: "IMAP", 443: "HTTPS", 465: "SMTPS", 587: "SMTP",
  993: "IMAPS", 995: "POP3S", 3306: "MySQL", 3389: "RDP", 5432: "PostgreSQL",
  6379: "Redis", 8080: "HTTP-alt", 8443: "HTTPS-alt", 27017: "MongoDB",
};

function tryConnect(ip: string, port: number): Promise<{ open: boolean; latencyMs: number }> {
  return new Promise((resolve) => {
    const started = Date.now();
    const socket = new net.Socket();
    let settled = false;
    const finish = (open: boolean) => {
      if (settled) return;
      settled = true;
      socket.destroy();
      resolve({ open, latencyMs: Date.now() - started });
    };
    socket.setTimeout(TIMEOUT_MS);
    socket.once("connect", () => finish(true));
    socket.once("timeout", () => finish(false));
    socket.once("error", () => finish(false));
    socket.connect(port, ip);
  });
}

export async function POST(req: Request) {
  const limited = toolRateLimitByIp(req, "port", { max: 20, windowMs: 60_000 });
  if (limited) return limited;

  const body = (await req.json().catch(() => ({}))) as { host?: unknown; port?: unknown };
  const host = extractHost(typeof body.host === "string" ? body.host : "");
  const port = Number(body.port);

  if (!host) return jsonError("Enter a valid host.");
  if (!Number.isInteger(port) || port < 1 || port > 65535) {
    return jsonError("Port must be an integer between 1 and 65535.");
  }

  try {
    const { host: resolved, addresses } = await resolvePublicHost(host);
    const ip = addresses[0];
    // Extra per-target throttle so we can't be used to sweep one host's ports.
    const sweep = checkRateLimit(`portsweep:${trustedClientIp(req)}:${resolved}`, {
      max: 30,
      windowMs: 60_000,
    });
    if (!sweep.ok) return jsonError(`Too many checks against that host. Try again in ${sweep.retryAfterSec}s.`, 429);

    const result = await tryConnect(ip, port);
    return NextResponse.json({
      ok: true,
      host: resolved,
      ip,
      port,
      service: COMMON[port] ?? null,
      open: result.open,
      latencyMs: result.open ? result.latencyMs : null,
    });
  } catch (e) {
    if (e instanceof BlockedHostError) return jsonError(e.message, 403);
    return jsonError("Port check failed.", 502);
  }
}

=== ToolShell ===
import Link from "next/link";
import { Reveal } from "./Reveal";
import { Eyebrow } from "./primitives";
import { IconArrow } from "./icons";

/**
 * Consistent layout wrapper for every free tool page.
 *
 *  1. A PageHero-style header — eyebrow (category) + tool name + one-line pitch,
 *     over the shared `.hero-aura` glow.
 *  2. The interactive tool UI, rendered inside a branded card (the `children`).
 *  3. An SEO content block below (What is X? / How to use / FAQ) so each page has
 *     real, indexable copy to rank on — the whole point of these SEO magnets.
 *
 * Server component: interactive tool bodies are their own "use client" islands
 * passed in as children.
 */

export type SeoBlock = { heading: string; body: React.ReactNode };
export type ToolFaq = { q: string; a: string };

export function ToolShell({
  category,
  title,
  description,
  children,
  about,
  steps,
  faq,
  related,
}: {
  category: string;
  title: string;
  description: string;
  children: React.ReactNode;
  /** Free-form SEO sections ("What is a subnet?", etc). */
  about?: SeoBlock[];
  /** Ordered "How to use" steps. */
  steps?: string[];
  faq?: ToolFaq[];
  /** Cross-links to sibling tools for internal linking / discovery. */
  related?: { label: string; href: string }[];
}) {
  return (
    <>
      {/* Header */}
      <section className="relative overflow-hidden">
        <div className="pointer-events-none absolute inset-0 -z-10 hero-aura" aria-hidden />
        <div className="rail pb-10 pt-16 sm:pt-20">
          <Reveal>
            <nav className="mb-5 flex items-center gap-2 text-xs text-slate-500">
              <Link href="/tools" className="transition-colors hover:text-slate-300">
                Free tools
              </Link>
              <span aria-hidden>/</span>
              <span className="text-slate-400">{title}</span>
            </nav>
            <Eyebrow pill>{category}</Eyebrow>
            <h1 className="mt-5 max-w-3xl text-3xl font-bold leading-[1.1] tracking-tight text-white sm:text-4xl lg:text-5xl text-balance">
              {title}
            </h1>
            <p className="mt-4 max-w-2xl text-lg leading-relaxed text-slate-400">{description}</p>
          </Reveal>
        </div>
      </section>

      {/* Tool UI */}
      <section className="relative">
        <div className="rail pb-16">
          <Reveal className="card p-5 sm:p-7">{children}</Reveal>
        </div>
      </section>

      {/* SEO content */}
      {(about?.length || steps?.length || faq?.length) && (
        <section className="tone-panel py-16 sm:py-20">
          <div className="rail">
            <div className="grid gap-12 lg:grid-cols-[1.4fr_1fr]">
              <div className="space-y-10">
                {about?.map((s) => (
                  <div key={s.heading}>
                    <h2 className="text-xl font-semibold text-white sm:text-2xl">{s.heading}</h2>
                    <div className="mt-3 space-y-3 text-[15px] leading-relaxed text-slate-400">
                      {s.body}
                    </div>
                  </div>
                ))}

                {steps && steps.length > 0 && (
                  <div>
                    <h2 className="text-xl font-semibold text-white sm:text-2xl">How to use it</h2>
                    <ol className="mt-4 space-y-3">
                      {steps.map((step, i) => (
                        <li key={i} className="flex gap-3 text-[15px] leading-relaxed text-slate-300">
                          <span className="mt-0.5 flex h-6 w-6 shrink-0 items-center justify-center rounded-full border border-brand-500/30 bg-brand-500/10 text-xs font-semibold text-brand-200">
                            {i + 1}
                          </span>
                          <span>{step}</span>
                        </li>
                      ))}
                    </ol>
                  </div>
                )}

                {faq && faq.length > 0 && (
                  <div>
                    <h2 className="text-xl font-semibold text-white sm:text-2xl">
                      Frequently asked questions
                    </h2>
                    <div className="mt-4 space-y-3">
                      {faq.map((f) => (
                        <details key={f.q} className="card group p-4">
                          <summary className="cursor-pointer list-none text-[15px] font-semibold text-white marker:hidden">
                            <span className="flex items-center justify-between gap-3">
                              {f.q}
                              <span className="text-slate-500 transition-transform group-open:rotate-45">
                                +
                              </span>
                            </span>
                          </summary>
                          <p className="mt-3 text-[15px] leading-relaxed text-slate-400">{f.a}</p>
                        </details>
                      ))}
                    </div>
                  </div>
                )}
              </div>

              {/* Sidebar: related tools + CTA */}
              <aside className="space-y-6">
                {related && related.length > 0 && (
                  <div className="card">
                    <p className="section-label mb-3">Related tools</p>
                    <ul className="space-y-1">
                      {related.map((r) => (
                        <li key={r.href}>
                          <Link
                            href={r.href}
                            className="flex items-center justify-between rounded-lg px-2 py-2 text-sm text-slate-300 transition-colors hover:bg-white/[0.04] hover:text-white"
                          >
                            {r.label}
                            <IconArrow size={14} />
                          </Link>
                        </li>
                      ))}
                    </ul>
                  </div>
                )}

                <div className="card glow-brand bg-gradient-to-br from-brand-500/10 to-accent-blue/5">
                  <h3 className="text-base font-semibold text-white">Need a real server?</h3>
                  <p className="mt-2 text-sm leading-relaxed text-slate-400">
                    Nxeon ships NVMe cloud VPS with full root access, a dedicated IPv4, and
                    one-click apps — deployed in under a minute.
                  </p>
                  <Link href="/vps" className="btn-primary mt-4 w-full">
                    Explore VPS hosting
                    <IconArrow size={15} />
                  </Link>
                </div>
              </aside>
            </div>
          </div>
        </section>
      )}
    </>
  );
}

/** JSON-LD FAQ schema helper — drop into a tool page for rich results. */
export function FaqJsonLd({ faq }: { faq: ToolFaq[] }) {
  const data = {
    "@context": "https://schema.org",
    "@type": "FAQPage",
    mainEntity: faq.map((f) => ({
      "@type": "Question",
      name: f.q,
      acceptedAnswer: { "@type": "Answer", text: f.a },
    })),
  };
  return (
    <script type="application/ld+json" dangerouslySetInnerHTML={{ __html: JSON.stringify(data) }} />
  );
}
