"use client";

import { useState } from "react";
import { Field, ErrorNote, RunButton, ResultCard, KeyValue } from "./ui";

const PRESETS = [
  { label: "SSH · 22", port: 22 },
  { label: "HTTP · 80", port: 80 },
  { label: "HTTPS · 443", port: 443 },
  { label: "MySQL · 3306", port: 3306 },
  { label: "Postgres · 5432", port: 5432 },
];

type Result = {
  host: string;
  ip: string;
  port: number;
  service: string | null;
  open: boolean;
  latencyMs: number | null;
};

export function PortCheckerTool() {
  const [host, setHost] = useState("");
  const [port, setPort] = useState("443");
  const [loading, setLoading] = useState(false);
  const [error, setError] = useState("");
  const [result, setResult] = useState<Result | null>(null);

  async function run(e: React.FormEvent) {
    e.preventDefault();
    if (!host.trim()) return;
    setLoading(true);
    setError("");
    setResult(null);
    try {
      const res = await fetch("/api/tools/port-checker", {
        method: "POST",
        headers: { "content-type": "application/json" },
        body: JSON.stringify({ host, port: Number(port) }),
      });
      const data = await res.json();
      if (!res.ok || !data.ok) throw new Error(data.error || "Check failed.");
      setResult(data);
    } catch (err) {
      setError(err instanceof Error ? err.message : "Check failed.");
    } finally {
      setLoading(false);
    }
  }

  return (
    <div className="space-y-5">
      <form onSubmit={run} className="flex flex-col gap-3 sm:flex-row sm:items-end">
        <div className="flex-1">
          <Field label="Host or IP">
            <input
              className="input"
              placeholder="example.com"
              value={host}
              onChange={(e) => setHost(e.target.value)}
              autoCapitalize="none"
              autoCorrect="off"
              spellCheck={false}
            />
          </Field>
        </div>
        <div className="w-full sm:w-32">
          <Field label="Port">
            <input
              className="input"
              inputMode="numeric"
              placeholder="443"
              value={port}
              onChange={(e) => setPort(e.target.value.replace(/[^0-9]/g, ""))}
            />
          </Field>
        </div>
        <RunButton loading={loading} type="submit">
          Check
        </RunButton>
      </form>

      <div className="flex flex-wrap gap-2">
        {PRESETS.map((p) => (
          <button
            key={p.port}
            type="button"
            onClick={() => setPort(String(p.port))}
            className="rounded-full border border-white/10 bg-white/[0.03] px-3 py-1 text-xs text-slate-400 transition-colors hover:border-brand-500/30 hover:text-white"
          >
            {p.label}
          </button>
        ))}
      </div>

      <ErrorNote>{error}</ErrorNote>

      {result && (
        <ResultCard>
          <div className="mb-3 flex items-center gap-2">
            <span
              className={`inline-flex items-center gap-2 rounded-full px-3 py-1 text-sm font-semibold ${
                result.open
                  ? "border border-emerald-500/30 bg-emerald-500/10 text-emerald-300"
                  : "border border-red-500/30 bg-red-500/10 text-red-300"
              }`}
            >
              <span className={`h-2 w-2 rounded-full ${result.open ? "bg-emerald-400" : "bg-red-400"}`} />
              Port {result.port} is {result.open ? "OPEN" : "closed / filtered"}
            </span>
          </div>
          <KeyValue
            rows={[
              ["Host", result.host],
              ["Resolved IP", <span className="font-mono text-[13px]">{result.ip}</span>],
              ["Service", result.service],
              ["Latency", result.latencyMs != null ? `${result.latencyMs} ms` : null],
            ]}
          />
        </ResultCard>
      )}
    </div>
  );
}

