=== coupon-order.ts ===
/**
 * Coupons applied at CHECKOUT of a service (not fungible wallet credit).
 *
 * This is what makes "one free month on the Starter VPS" mean exactly that:
 *  - `serviceKind` + `planSlug` lock the coupon to a product family and/or a
 *    single plan, so it cannot be spent on a bigger plan or a different service;
 *  - `maxTermMonths` caps how many months of the term it may discount, so a
 *    percentage/free coupon cannot be stretched over a 12-month order to hand
 *    someone a year for free.
 *
 * Pure and framework-free so the money maths is unit-tested. The atomic
 * redemption claim (count + per-user + per-IP guards) lives in lib/order.ts.
 */

export type CouponServiceKind = "ANY" | "VPS" | "GAME";
export type CouponKind = "PERCENT" | "FIXED_CENTS" | "CREDIT_CENTS";

/** The coupon fields the order maths needs. */
export type OrderCoupon = {
  kind: CouponKind;
  value: number;
  serviceKind: CouponServiceKind;
  planSlug: string | null;
  maxTermMonths: number | null;
  active: boolean;
  expiresAt: Date | null;
  maxRedemptions: number | null;
  timesRedeemed: number;
  minAmountCents: number | null;
};

export type OrderContext = {
  /** "VPS" or "GAME" — what the customer is buying. */
  serviceKind: "VPS" | "GAME";
  /** The plan's slug, matched against `coupon.planSlug`. */
  planSlug: string;
  /** The plan's REGULAR monthly price (before term/seasonal discounts), cents. */
  planMonthlyCents: number;
  /** The term the customer chose, in months. */
  termMonths: number;
  /** What the plan portion of the order actually costs (first-term, cents). */
  planChargeCents: number;
};

/** Does this coupon apply to the thing being bought? */
export function couponMatchesService(coupon: Pick<OrderCoupon, "serviceKind" | "planSlug">, ctx: Pick<OrderContext, "serviceKind" | "planSlug">): boolean {
  if (coupon.serviceKind !== "ANY" && coupon.serviceKind !== ctx.serviceKind) return false;
  if (coupon.planSlug && coupon.planSlug.toLowerCase() !== ctx.planSlug.toLowerCase()) return false;
  return true;
}

export type CouponOrderVerdict =
  | { ok: true; discountCents: number; label: string }
  | { ok: false; error: string };

/** "1 month free on Starter", "20% off (first 1 month)", "$5.00 off"… */
function describe(coupon: Pick<OrderCoupon, "kind" | "value">, cappedMonths: number, termMonths: number): string {
  const monthNote = cappedMonths < termMonths ? ` (first ${cappedMonths} month${cappedMonths === 1 ? "" : "s"})` : "";
  switch (coupon.kind) {
    case "PERCENT":
      return coupon.value >= 100 ? `${cappedMonths} month${cappedMonths === 1 ? "" : "s"} free` : `${coupon.value}% off${monthNote}`;
    case "FIXED_CENTS":
      return `$${(coupon.value / 100).toFixed(2)} off`;
    default:
      return "discount";
  }
}

/**
 * Validate a coupon against an order and compute the discount, in cents.
 *
 * Only PERCENT and FIXED_CENTS apply at checkout (CREDIT_CENTS is a wallet-credit
 * kind and is rejected here). The discount is bounded three ways and never
 * exceeds the plan charge:
 *   - PERCENT is applied to at most `maxTermMonths` months of the plan's monthly
 *     price — THE cap that stops "100% off" on a 12-month order being a year free;
 *   - FIXED_CENTS is a flat amount, still capped at the plan charge;
 *   - both are clamped to `planChargeCents` so a coupon can zero a line but never
 *     make it negative (which would mint wallet credit).
 */
export function couponOrderDiscountCents(coupon: OrderCoupon, ctx: OrderContext, now: Date): CouponOrderVerdict {
  if (!coupon.active) return { ok: false, error: "That code isn’t valid." };
  if (coupon.kind === "CREDIT_CENTS") return { ok: false, error: "That code is for wallet credit, not checkout." };
  if (coupon.expiresAt && coupon.expiresAt.getTime() < now.getTime()) return { ok: false, error: "That code has expired." };
  if (coupon.maxRedemptions !== null && coupon.timesRedeemed >= coupon.maxRedemptions) {
    return { ok: false, error: "That code has been fully claimed." };
  }
  if (!couponMatchesService(coupon, ctx)) {
    return { ok: false, error: "That code doesn’t apply to this plan." };
  }
  if (coupon.minAmountCents !== null && ctx.planChargeCents < coupon.minAmountCents) {
    return { ok: false, error: `This code needs an order of at least $${(coupon.minAmountCents / 100).toFixed(2)}.` };
  }

  const term = Math.max(1, Math.floor(ctx.termMonths || 1));
  // How many months the discount may touch — the "no year free" cap.
  const cappedMonths = coupon.maxTermMonths && coupon.maxTermMonths > 0 ? Math.min(coupon.maxTermMonths, term) : term;

  let discount: number;
  if (coupon.kind === "PERCENT") {
    const pct = Math.min(100, Math.max(0, coupon.value));
    // The discountable base is the capped months at the REGULAR monthly price —
    // not the whole (possibly term-discounted) charge — so "1 month free" is one
    // month of the plan regardless of a 12-month term's own discount.
    const base = Math.min(ctx.planMonthlyCents * cappedMonths, ctx.planChargeCents);
    discount = Math.round((base * pct) / 100);
  } else {
    discount = coupon.value;
  }

  discount = Math.max(0, Math.min(discount, ctx.planChargeCents));
  if (discount <= 0) return { ok: false, error: "That code has no effect on this order." };
  return { ok: true, discountCents: discount, label: describe(coupon, cappedMonths, term) };
}

/**
 * A stable, non-reversible hash of a claimant IP, for the once-per-person guard.
 * We store the hash, never the raw IP — the check only needs equality, and a
 * plaintext IP log of everyone who claimed a promo is a liability we don't want.
 * `salt` comes from the app secret so hashes aren't portable across deployments.
 */
export function hashIp(ip: string, salt: string): string {
  const clean = String(ip ?? "").trim();
  if (!clean) return "";
  // Lazy require so this module stays importable in any context; crypto is builtin.
  const { createHash } = require("node:crypto") as typeof import("node:crypto");
  return createHash("sha256").update(`${salt}:${clean}`).digest("hex");
}

/** Human summary of a coupon's scope for the admin list / customer preview. */
export function describeCouponScope(coupon: Pick<OrderCoupon, "serviceKind" | "planSlug" | "maxTermMonths">): string {
  const parts: string[] = [];
  if (coupon.planSlug) parts.push(`${coupon.planSlug} plan only`);
  else if (coupon.serviceKind !== "ANY") parts.push(`${coupon.serviceKind} only`);
  if (coupon.maxTermMonths) parts.push(`max ${coupon.maxTermMonths} month${coupon.maxTermMonths === 1 ? "" : "s"}`);
  return parts.join(" · ") || "any service";
}

