/**
 * Compose a standard transactional email from structured parts. Keeps every
 * template terse and uniform: eyebrow → heading → body blocks → optional CTA →
 * optional footnote, all wrapped with a preheader.
 */
function build(opts: {
  template: string;
  subject: string;
