export type NotifyKind = keyof typeof NOTIFY_KINDS;

/**
 * Tier of a message kind. An unregistered kind resolves to CRITICAL on purpose:
 * the failure mode of a mis-typed or forgotten kind must be "delivered anyway",
 * never "silently dropped".
 */
export function notifyTier(kind: NotifyKind): NotifyTier {
  return (NOTIFY_KINDS as Record<string, NotifyTier>)[kind] ?? "CRITICAL";
}

/**
 * Does this (kind, channel) pair depend on the customer's preferences at all?
 *
 * `false` means the answer is unconditionally "deliver", so callers can skip the
 * preference lookup entirely — the gate costs nothing on the critical paths.
 */
export function isSuppressible(kind: NotifyKind, channel: NotifyChannel): boolean {
  const tier = notifyTier(kind);
  if (tier === "CRITICAL") return false;
  if (tier === "ACCOUNT") {
    // Email only. The in-app bell is the durable record inside the portal, and
    // the toggle the customer ticked says "email" — hiding an activity notice
    // from the portal would recreate the very failure this policy exists to
    // cure (information that quietly went missing), while suppressing the mail
    // is exactly what was asked for.
    return channel === "email";
  }
  return true; // PRODUCT — marketing has no business on a channel they declined.
}

/** Decide delivery from already-loaded preferences. */
export function mayDeliver(
  prefs: NotificationPrefs,
  kind: NotifyKind,
  channel: NotifyChannel,
): boolean {
  if (!isSuppressible(kind, channel)) return true;
  return notifyTier(kind) === "PRODUCT" ? prefs.product : prefs.email;
}

