export function areaForHref(href: string): Area {
  return HREF_AREA[href] ?? "platform";
}

export function canAccessHref(role: Role, href: string): boolean {
  return canAccess(role, areaForHref(href));
}

/**
 * Server-side page guard. Redirects to /login if signed out, or back to the
 * overview if the (staff) user's role can't reach this area. Returns the real
 * signed-in user (impersonation is refused elsewhere in the admin layout).
 */
export async function requireArea(area: Area): Promise<User> {
  const user = await realUser();
  if (!user) redirect("/login");
  if (!isStaff(user.role)) redirect("/dashboard");
  if (!canAccess(user.role, area)) redirect("/admin");
  return user;
}

export async function saveSettings(
  section: string,
  _prev: Result | undefined,
  formData: FormData,
): Promise<Result> {
  const fields = SECTION_FIELDS[section];
  if (!fields) return { error: "Unknown settings section." };

  const area = BILLING_SECTIONS.has(section) ? "billing" : "platform";
  const user = await requireArea(area);

  const changes: { key: string; value: string }[] = [];

  for (const f of fields) {
    const raw = formData.get(f.key);

    if (f.type === "bool") {
      changes.push({ key: f.key, value: raw ? "true" : "false" });
      continue;
    }

    if (f.type === "secret") {
      const v = (raw ?? "").toString();
      if (v.trim() === "") continue; // never clear/overwrite a stored secret with blank
      // Encrypt at rest. `smtp_pass` was the last secret in the DB stored as
      // plaintext while mailbox passwords and the Cloudflare token both use the
      // AES-256-GCM box. Read-back in lib/mailer.ts decrypts, tolerating a legacy
      // plaintext row until it is next saved. Never render — SecretField shows
      // only `isSet` — so this closes an at-rest exposure, not a live leak.
      changes.push({ key: f.key, value: encryptSecret(v) });
      continue;
    }

    if (f.type === "enum") {
      const s = (raw ?? "").toString().trim();
      if (s === "") {
        changes.push({ key: f.key, value: SETTINGS_DEFAULTS[f.key as keyof typeof SETTINGS_DEFAULTS] ?? "" });
        continue;
      }
      // A <select> constrains the browser, not the request.
      if (!f.values?.includes(s)) {
        return { error: `“${f.key}” must be one of: ${f.values?.join(", ")}.` };
      }
      changes.push({ key: f.key, value: s });
      continue;
    }

    if (f.type === "int" || f.type === "num") {
      const s = (raw ?? "").toString().trim();
      if (s === "") {
        changes.push({ key: f.key, value: SETTINGS_DEFAULTS[f.key as keyof typeof SETTINGS_DEFAULTS] ?? "0" });
        continue;
      }
      const n = Number(s);
      if (!Number.isFinite(n)) return { error: `“${f.key}” must be a number.` };
      // Refuse rather than clamp, so the stored row always equals what the operator
      // can read back off the field. Silent clamping is how a panel ends up showing
      // one number while the platform enforces another.
      if (f.min !== undefined && n < f.min) {
        return { error: `“${f.key}” must be at least ${f.min} (you entered ${s}).` };
      }
      if (f.max !== undefined && n > f.max) {
        return { error: `“${f.key}” must be ${f.max} or less (you entered ${s}).` };
