import { NextResponse } from "next/server";
import net from "node:net";
import { resolveSrv } from "node:dns/promises";
import { jsonError } from "@/lib/tools/api";
import { toolRateLimitByIp, trustedClientIp } from "@/app/api/_lib/client-ip";
import { checkRateLimit } from "@/lib/rate-limit";
import { extractHost, resolvePublicHost, BlockedHostError } from "@/lib/tools/net-guard";

export const runtime = "nodejs";
export const dynamic = "force-dynamic";

/**
 * Minecraft Server List Ping (Java Edition) over raw TCP.
 *
 * Implements the modern JSON handshake: we send a Handshake packet (next state =
 * status) followed by a Status Request, then read the length-prefixed JSON status
 * the server replies with — players online/max, MOTD, version, favicon presence —
 * and report the round-trip time as latency.
 *
 * SSRF-guarded like every other network tool: the (optionally SRV-resolved)
 * target is resolved to a public IP via `resolvePublicHost`, private/loopback/
 * reserved addresses are refused, and we connect to the vetted IP. Rate-limited
 * per IP and per target. Offline/timeout is a clean 200 with `online:false`, not
 * an error — an offline server is a normal, useful answer for this tool.
 */

const DEFAULT_PORT = 25565;
const CONNECT_TIMEOUT_MS = 5000;
const READ_TIMEOUT_MS = 5000;
const PROTOCOL_VERSION = 47; // 1.8 — the most widely accepted handshake version.
const MAX_JSON_BYTES = 512 * 1024;

/** Encode a non-negative integer as a Minecraft VarInt. */
function writeVarInt(value: number): Buffer {
  const bytes: number[] = [];
  let v = value >>> 0;
  for (;;) {
    if ((v & ~0x7f) === 0) {
      bytes.push(v);
      break;
    }
    bytes.push((v & 0x7f) | 0x80);
    v >>>= 7;
  }
  return Buffer.from(bytes);
}

/** Read a VarInt from `buf` at `offset`. Returns null if more bytes are needed. */
function readVarInt(buf: Buffer, offset: number): { value: number; size: number } | null {
  let numRead = 0;
  let result = 0;
  let byte: number;
  do {
    if (offset + numRead >= buf.length) return null; // incomplete
    byte = buf[offset + numRead];
    result |= (byte & 0x7f) << (7 * numRead);
    numRead++;
    if (numRead > 5) return { value: result >>> 0, size: numRead }; // malformed, bail
  } while ((byte & 0x80) !== 0);
  return { value: result >>> 0, size: numRead };
}

function encodeString(s: string): Buffer {
  const body = Buffer.from(s, "utf8");
  return Buffer.concat([writeVarInt(body.length), body]);
}

/** Wrap a packet body (already including its packet-id VarInt) with a length prefix. */
function framePacket(body: Buffer): Buffer {
  return Buffer.concat([writeVarInt(body.length), body]);
}

/** Pull readable plain text out of a MOTD, which may be a string or a chat component. */
function extractMotd(desc: unknown): string {
  if (typeof desc === "string") return desc;
  if (!desc || typeof desc !== "object") return "";
  const d = desc as Record<string, unknown>;
  let out = typeof d.text === "string" ? d.text : "";
  const extra = d.extra;
  if (Array.isArray(extra)) for (const part of extra) out += extractMotd(part);
  // Strip section-sign colour/format codes.
  return out.replace(/§[0-9a-fk-or]/gi, "").trim();
}

type PingResult = {
  online: true;
  versionName: string | null;
  protocol: number | null;
  playersOnline: number | null;
  playersMax: number | null;
  sample: string[];
  motd: string;
  favicon: boolean;
  latencyMs: number;
};

function pingServer(ip: string, port: number, hostname: string): Promise<PingResult> {
  return new Promise((resolve, reject) => {
    const socket = new net.Socket();
    let settled = false;
    let chunks: Buffer = Buffer.alloc(0);
    let started = 0;

    const fail = (err: Error) => {
      if (settled) return;
      settled = true;
      socket.destroy();
      reject(err);
    };

    socket.setTimeout(CONNECT_TIMEOUT_MS);
    socket.once("timeout", () => fail(new Error("timeout")));
    socket.once("error", (e) => fail(e));

    socket.connect(port, ip, () => {
      socket.setTimeout(READ_TIMEOUT_MS);
      started = Date.now();
      // Handshake: id 0x00, protocol, server address, port (u16), next state = 1.
      const handshakeBody = Buffer.concat([
        writeVarInt(0x00),
        writeVarInt(PROTOCOL_VERSION),
        encodeString(hostname),
        Buffer.from([(port >> 8) & 0xff, port & 0xff]),
        writeVarInt(1),
      ]);
      // Status request: id 0x00, empty body.
      const statusRequest = framePacket(writeVarInt(0x00));
      socket.write(Buffer.concat([framePacket(handshakeBody), statusRequest]));
    });

    socket.on("data", (data) => {
      chunks = Buffer.concat([chunks, data]);
      // Parse: [packet length VarInt][packet id VarInt = 0][json length VarInt][json].
      const lenHeader = readVarInt(chunks, 0);
      if (!lenHeader) return; // need more bytes for the frame length
      const packetLen = lenHeader.value;
      if (packetLen > MAX_JSON_BYTES) return fail(new Error("response too large"));
      const total = lenHeader.size + packetLen;
      if (chunks.length < total) return; // wait for the full frame

      let cursor = lenHeader.size;
      const idHeader = readVarInt(chunks, cursor);
      if (!idHeader) return fail(new Error("malformed response"));
      cursor += idHeader.size;
      const jsonLen = readVarInt(chunks, cursor);
      if (!jsonLen) return fail(new Error("malformed response"));
      cursor += jsonLen.size;
      const jsonBuf = chunks.subarray(cursor, cursor + jsonLen.value);

      let parsed: Record<string, unknown>;
      try {
        parsed = JSON.parse(jsonBuf.toString("utf8"));
      } catch {
        return fail(new Error("could not parse server status"));
      }

      settled = true;
      const latencyMs = Date.now() - started;
      socket.destroy();

      const version = (parsed.version ?? {}) as Record<string, unknown>;
      const players = (parsed.players ?? {}) as Record<string, unknown>;
      const sampleRaw = Array.isArray(players.sample) ? players.sample : [];
      const sample = sampleRaw
        .map((p) => (p && typeof p === "object" ? String((p as Record<string, unknown>).name ?? "") : ""))
        .filter(Boolean)
        .slice(0, 12);

      resolve({
        online: true,
        versionName: typeof version.name === "string" ? version.name.replace(/§[0-9a-fk-or]/gi, "") : null,
        protocol: typeof version.protocol === "number" ? version.protocol : null,
        playersOnline: typeof players.online === "number" ? players.online : null,
        playersMax: typeof players.max === "number" ? players.max : null,
        sample,
        motd: extractMotd(parsed.description),
        favicon: typeof parsed.favicon === "string" && parsed.favicon.length > 0,
        latencyMs,
      });
    });
  });
}

export async function POST(req: Request) {
  const limited = toolRateLimitByIp(req, "mc-status", { max: 20, windowMs: 60_000 });
  if (limited) return limited;

  const body = (await req.json().catch(() => ({}))) as { host?: unknown; port?: unknown };
  const rawHost = extractHost(typeof body.host === "string" ? body.host : "");
  if (!rawHost) return jsonError("Enter a valid server address.");

  const portGiven = body.port !== undefined && body.port !== null && String(body.port).trim() !== "";
  let port = portGiven ? Number(body.port) : DEFAULT_PORT;
  let targetHost = rawHost;

  // Minecraft servers commonly advertise their real host:port via an SRV record
  // (_minecraft._tcp.<domain>). Only consult it when the visitor didn't pin a
  // port — an explicit port always wins.
  if (!portGiven && !net.isIP(rawHost)) {
    try {
      const srv = await resolveSrv(`_minecraft._tcp.${rawHost}`);
      if (srv.length > 0) {
        targetHost = srv[0].name.replace(/\.$/, "");
        port = srv[0].port;
      }
    } catch {
      /* no SRV record — use the host/port as given */
    }
  }

  if (!Number.isInteger(port) || port < 1 || port > 65535) {
    return jsonError("Port must be an integer between 1 and 65535.");
  }

  try {
    const { host: resolved, addresses } = await resolvePublicHost(targetHost);
    const ip = addresses[0];

    const sweep = checkRateLimit(`mcping:${trustedClientIp(req)}:${resolved}:${port}`, {
      max: 30,
      windowMs: 60_000,
    });
    if (!sweep.ok) return jsonError(`Too many checks against that server. Try again in ${sweep.retryAfterSec}s.`, 429);

    try {
      const result = await pingServer(ip, port, resolved);
      return NextResponse.json({ ok: true, host: resolved, port, ...result });
    } catch {
      // Any protocol/connection failure = the server is unreachable for players.
      return NextResponse.json({ ok: true, host: resolved, port, online: false });
    }
  } catch (e) {
    if (e instanceof BlockedHostError) return jsonError(e.message, 403);
    return jsonError("Status check failed.", 502);
  }
}

"use client";

import Link from "next/link";
import { useState } from "react";
import { Field, ErrorNote, RunButton, ResultCard, KeyValue } from "./ui";

type Result = {
  host: string;
  port: number;
  online: boolean;
  versionName?: string | null;
  protocol?: number | null;
  playersOnline?: number | null;
  playersMax?: number | null;
  sample?: string[];
  motd?: string;
  favicon?: boolean;
  latencyMs?: number;
};

export function MinecraftStatusTool() {
  const [host, setHost] = useState("");
  const [port, setPort] = useState("");
  const [loading, setLoading] = useState(false);
  const [error, setError] = useState("");
  const [result, setResult] = useState<Result | null>(null);

  async function run(e: React.FormEvent) {
    e.preventDefault();
    if (!host.trim()) return;
    setLoading(true);
    setError("");
    setResult(null);
    try {
      const res = await fetch("/api/tools/mc-status", {
        method: "POST",
        headers: { "content-type": "application/json" },
        body: JSON.stringify({ host, port: port.trim() ? Number(port) : undefined }),
      });
      const data = await res.json();
      if (!res.ok || !data.ok) throw new Error(data.error || "Check failed.");
      setResult(data);
    } catch (err) {
      setError(err instanceof Error ? err.message : "Check failed.");
    } finally {
      setLoading(false);
    }
  }

  return (
    <div className="space-y-5">
      <form onSubmit={run} className="flex flex-col gap-3 sm:flex-row sm:items-end">
        <div className="flex-1">
          <Field label="Server address" hint="A domain or IP, e.g. play.hypixel.net. We'll follow SRV records automatically.">
            <input
              className="input"
              placeholder="play.example.net"
              value={host}
              onChange={(e) => setHost(e.target.value)}
              autoCapitalize="none"
              autoCorrect="off"
              spellCheck={false}
            />
          </Field>
        </div>
        <div className="w-full sm:w-32">
          <Field label="Port">
            <input
              className="input"
              inputMode="numeric"
              placeholder="25565"
              value={port}
              onChange={(e) => setPort(e.target.value.replace(/[^0-9]/g, ""))}
            />
          </Field>
        </div>
        <RunButton loading={loading} type="submit">
          Check status
        </RunButton>
      </form>

      <ErrorNote>{error}</ErrorNote>

      {result && (
        <ResultCard>
          <div className="mb-3 flex flex-wrap items-center gap-2">
            <span
              className={`inline-flex items-center gap-2 rounded-full px-3 py-1 text-sm font-semibold ${
                result.online
                  ? "border border-emerald-500/30 bg-emerald-500/10 text-emerald-300"
                  : "border border-red-500/30 bg-red-500/10 text-red-300"
              }`}
            >
              <span className={`h-2 w-2 rounded-full ${result.online ? "bg-emerald-400" : "bg-red-400"}`} />
              {result.host}:{result.port} is {result.online ? "ONLINE" : "offline / unreachable"}
            </span>
            {result.online && result.playersOnline != null && result.playersMax != null && (
              <span className="rounded-full border border-brand-500/25 bg-brand-500/10 px-3 py-1 text-sm font-semibold text-brand-200">
                {result.playersOnline} / {result.playersMax} players
              </span>
            )}
          </div>

          {result.online ? (
            <>
              {result.motd && (
                <p className="mb-3 whitespace-pre-wrap rounded-lg border border-white/[0.06] bg-navy-950/60 px-3 py-2 font-mono text-[13px] text-slate-300">
                  {result.motd}
                </p>
              )}
              <KeyValue
                rows={[
                  ["Version", result.versionName],
                  ["Protocol", result.protocol != null ? String(result.protocol) : null],
                  ["Players", result.playersOnline != null ? `${result.playersOnline} / ${result.playersMax ?? "?"}` : null],
                  ["Online now", result.sample && result.sample.length > 0 ? result.sample.join(", ") : null],
                  ["Latency", result.latencyMs != null ? `${result.latencyMs} ms` : null],
                ]}
              />
            </>
          ) : (
            <p className="text-sm text-slate-400">
              No Minecraft server answered on that address and port. Double-check the host, the port
              (default 25565), and that the server is running and reachable from the public internet.
            </p>
          )}
        </ResultCard>
      )}

      <div className="rounded-xl border border-brand-500/20 bg-gradient-to-br from-brand-500/10 to-accent-blue/5 p-4">
        <p className="text-sm text-slate-300">
          Lagging or offline too often?{" "}
          <Link href="/minecraft-server-hosting" className="font-semibold text-brand-300 hover:text-brand-200">
            Nxeon Minecraft hosting
          </Link>{" "}
          runs on high-clock NVMe boxes with a dedicated IP and one-click modpacks — spun up in under a minute.
        </p>
      </div>
    </div>
  );
}

