import { NextResponse } from "next/server";
import { toolRateLimitByIp } from "@/app/api/_lib/client-ip";

export const runtime = "nodejs";
export const dynamic = "force-dynamic";

/**
 * Tiny latency probe for the browser Ping / Latency Test tool
 * (/tools/latency-test). It does nothing but return 200 as fast as possible with
 * a no-store header, so repeated client fetches measure round-trip time to the
 * Nxeon edge rather than any work this handler does.
 *
 * Rate-limited generously (a latency test fires ~10-20 quick requests); the cap
 * only exists so the endpoint can't be turned into a flood amplifier.
 */
export async function GET(req: Request) {
  const limited = toolRateLimitByIp(req, "ping", { max: 240, windowMs: 60_000 });
  if (limited) return limited;
  return new NextResponse(JSON.stringify({ ok: true, t: Date.now() }), {
    status: 200,
    headers: {
      "content-type": "application/json",
      "cache-control": "no-store, no-cache, must-revalidate",
    },
  });
}

export function HEAD() {
  return new NextResponse(null, { status: 200, headers: { "cache-control": "no-store" } });
}

"use client";

import Link from "next/link";
import { useRef, useState } from "react";
import { RunButton, ResultCard, KeyValue } from "./ui";

type Sample = { ms: number };

const SAMPLES = 15;

function quality(avg: number): { label: string; tone: string } {
  if (avg < 40) return { label: "Excellent", tone: "text-emerald-300" };
  if (avg < 80) return { label: "Great", tone: "text-emerald-300" };
  if (avg < 150) return { label: "Good", tone: "text-amber-300" };
  return { label: "High", tone: "text-red-300" };
}

export function LatencyTestTool() {
  const [running, setRunning] = useState(false);
  const [progress, setProgress] = useState(0);
  const [samples, setSamples] = useState<Sample[]>([]);
  const [done, setDone] = useState(false);
  const abort = useRef(false);

  async function run() {
    setRunning(true);
    setDone(false);
    setSamples([]);
    setProgress(0);
    abort.current = false;
    const collected: Sample[] = [];

    // One warm-up request so DNS/TLS/connection setup doesn't skew the first sample.
    try {
      await fetch(`/api/tools/ping?warmup=1`, { cache: "no-store" });
    } catch {
      /* ignore warm-up failure */
    }

    for (let i = 0; i < SAMPLES; i++) {
      if (abort.current) break;
      const start = performance.now();
      try {
        const res = await fetch(`/api/tools/ping?n=${i}&_=${Date.now()}`, { cache: "no-store" });
        if (!res.ok) continue;
        await res.arrayBuffer();
        const ms = performance.now() - start;
        collected.push({ ms });
        setSamples([...collected]);
      } catch {
        /* skip failed sample */
      }
      setProgress(Math.round(((i + 1) / SAMPLES) * 100));
      await new Promise((r) => setTimeout(r, 120));
    }

    setRunning(false);
    setDone(true);
  }

  const values = samples.map((s) => s.ms);
  const avg = values.length ? values.reduce((a, b) => a + b, 0) / values.length : 0;
  const min = values.length ? Math.min(...values) : 0;
  const max = values.length ? Math.max(...values) : 0;
  // Jitter: mean absolute deviation between consecutive samples.
  let jitter = 0;
  if (values.length > 1) {
    let sum = 0;
    for (let i = 1; i < values.length; i++) sum += Math.abs(values[i] - values[i - 1]);
    jitter = sum / (values.length - 1);
  }
  const q = quality(avg);

  return (
    <div className="space-y-5">
      <div className="flex flex-col items-start gap-3 sm:flex-row sm:items-center sm:justify-between">
        <p className="text-sm text-slate-400">
          Measures round-trip latency from your browser to the Nxeon edge over {SAMPLES} samples.
        </p>
        <RunButton loading={running} onClick={run}>
          {done ? "Run again" : "Start test"}
        </RunButton>
      </div>

      {(running || done) && (
        <div className="h-2 w-full overflow-hidden rounded-full bg-white/[0.06]">
          <div
            className="h-full rounded-full bg-gradient-to-r from-accent-blue to-brand-500 transition-all duration-200"
            style={{ width: `${progress}%` }}
          />
        </div>
      )}

      {values.length > 0 && (
        <ResultCard>
          <div className="mb-4 flex flex-wrap items-end gap-x-6 gap-y-2">
            <div>
              <p className="text-xs font-medium uppercase tracking-wide text-slate-500">Average latency</p>
              <p className="text-3xl font-bold text-white">
                {avg.toFixed(0)}
                <span className="ml-1 text-lg font-medium text-slate-400">ms</span>
              </p>
            </div>
            <p className={`text-sm font-semibold ${q.tone}`}>{q.label}</p>
          </div>
          <KeyValue
            rows={[
              ["Best", `${min.toFixed(0)} ms`],
              ["Worst", `${max.toFixed(0)} ms`],
              ["Jitter", `${jitter.toFixed(0)} ms`],
              ["Samples", `${values.length} / ${SAMPLES}`],
            ]}
          />
        </ResultCard>
      )}

      <div className="rounded-xl border border-brand-500/20 bg-gradient-to-br from-brand-500/10 to-accent-blue/5 p-4">
        <p className="text-sm text-slate-300">
          This is the latency you'd get to a Nxeon VPS in our Singapore region. Numbers depend on your
          own connection and distance to Singapore — {" "}
          <Link href="/vps" className="font-semibold text-brand-300 hover:text-brand-200">
            deploy a low-latency NVMe VPS
          </Link>{" "}
          and feel it for yourself.
        </p>
        <p className="mt-2 text-xs text-slate-500">
          We currently serve from a single Singapore data center, so this reflects APAC latency
          honestly — we won't pretend to have edges we don't.
        </p>
      </div>
    </div>
  );
}

