function ceilTo(mb: number, stepMB: number): number {
  return Math.ceil(mb / stepMB) * stepMB;
}

/** Compute raw RAM/CPU/storage requirements for a workload at a given scale. */
export function requirementsFor(workload: Workload, scale: number): { ramMB: number; cpuCores: number; storageGB: number } {
  const p = Math.max(0, Math.floor(scale || 0));
  switch (workload.id) {
    case "minecraft-vanilla":
      return { ramMB: ceilTo(Math.max(2048, 1024 + p * 200), 1024), cpuCores: p > 20 ? 3 : 2, storageGB: 25 };
    case "minecraft-modded":
      return { ramMB: ceilTo(Math.max(4096, 3072 + p * 300), 1024), cpuCores: p > 20 ? 4 : 3, storageGB: 30 };
    case "rust":
      return { ramMB: ceilTo(Math.max(8192, 6144 + p * 80), 1024), cpuCores: p > 100 ? 4 : 3, storageGB: 40 };
    case "palworld":
      return { ramMB: ceilTo(Math.max(16384, 14336 + p * 400), 1024), cpuCores: 4, storageGB: 40 };
    case "valheim":
      return { ramMB: ceilTo(Math.max(4096, 2048 + p * 300), 1024), cpuCores: 2, storageGB: 25 };
    case "ark":
      return { ramMB: ceilTo(Math.max(16384, 12288 + p * 400), 1024), cpuCores: 4, storageGB: 60 };
    case "7dtd":
      return { ramMB: ceilTo(Math.max(8192, 6144 + p * 300), 1024), cpuCores: 3, storageGB: 30 };
    case "zomboid":
      return { ramMB: ceilTo(Math.max(6144, 4096 + p * 200), 1024), cpuCores: 2, storageGB: 25 };
    case "enshrouded":
      return { ramMB: ceilTo(Math.max(6144, 4096 + p * 256), 1024), cpuCores: 3, storageGB: 30 };
    case "satisfactory":
      return { ramMB: ceilTo(Math.max(12288, 10240 + p * 512), 1024), cpuCores: 4, storageGB: 30 };
    case "terraria":
      return { ramMB: ceilTo(Math.max(4096, 2048 + p * 256), 1024), cpuCores: 2, storageGB: 20 };
    case "cs2":
      return { ramMB: ceilTo(Math.max(8192, 6144 + p * 128), 1024), cpuCores: 3, storageGB: 40 };
    case "fivem":
      return { ramMB: ceilTo(Math.max(8192, 6144 + p * 120), 1024), cpuCores: 4, storageGB: 40 };
    case "website":
      return { ramMB: p > 500000 ? 8192 : p > 100000 ? 4096 : 2048, cpuCores: p > 500000 ? 3 : p > 100000 ? 2 : 1, storageGB: 25 };
    case "wordpress":
      return { ramMB: p > 500000 ? 8192 : p > 100000 ? 4096 : 2048, cpuCores: p > 100000 ? 3 : 2, storageGB: 40 };
    case "nodejs":
      return { ramMB: p > 5000 ? 8192 : p > 1000 ? 4096 : 2048, cpuCores: p > 1000 ? 3 : 2, storageGB: 25 };
    case "docker":
      return { ramMB: 4096, cpuCores: 2, storageGB: 40 };
    case "discord-bot":
      return { ramMB: 2048, cpuCores: 1, storageGB: 25 };
    case "nextcloud":
      return { ramMB: 2048, cpuCores: 2, storageGB: 50 };
    case "vpn":
      return { ramMB: 2048, cpuCores: 1, storageGB: 25 };
    default:
      return { ramMB: 2048, cpuCores: 1, storageGB: 25 };
  }
}

/**
 * Full recommendation: raw requirements plus the smallest catalogue plan that
 * satisfies RAM and CPU, with honest notes when storage or the whole workload
 * outgrows the plan lineup.
 */
export function recommendPlan(workload: Workload, scale: number, plans: PlanSpec[]): Recommendation {
  const req = requirementsFor(workload, scale);
  const sorted = [...plans].sort((a, b) => a.ramMB - b.ramMB || a.cpuCores - b.cpuCores);
  const notes: string[] = [];

  let plan = sorted.find((pl) => pl.ramMB >= req.ramMB && pl.cpuCores >= req.cpuCores) ?? null;
  let exceedsCatalog = false;
  if (!plan && sorted.length > 0) {
    plan = sorted[sorted.length - 1];
    exceedsCatalog = true;
    notes.push(
      `This workload wants more than our largest standard plan (${plan.name}). Talk to us about a custom or dedicated box.`,
    );
  }

  if (plan && req.storageGB > plan.diskGB) {
    notes.push(
      `You'll want about ${req.storageGB} GB of storage — more than the ${plan.name} plan's ${plan.diskGB} GB. Add a block-storage volume as you grow.`,
    );
  }

  return { ...req, plan, exceedsCatalog, notes };
}

export function formatRam(mb: number): string {
  return mb >= 1024 ? `${(mb / 1024).toFixed(mb % 1024 === 0 ? 0 : 1)} GB` : `${mb} MB`;
}

