  const [workloadId, setWorkloadId] = useState(WORKLOADS[0].id);
  const workload = WORKLOADS.find((w) => w.id === workloadId) ?? WORKLOADS[0];
  const [scale, setScale] = useState<number>(workload.scaleDefault ?? 10);

  function pickWorkload(id: string) {
    const w = WORKLOADS.find((x) => x.id === id) ?? WORKLOADS[0];
    setWorkloadId(id);
    setScale(w.scaleDefault ?? 10);
