"use server";

import { revalidatePath } from "next/cache";
import { z } from "zod";
import { db } from "@/lib/db";
import { requireArea } from "@/lib/rbac";
import { setSetting } from "@/lib/settings";
import { logEvent } from "@/lib/log";

type ActionState = { error?: string; ok?: boolean };

const SOURCES = ["INTERNAL", "GOOGLE", "TRUSTPILOT", "HOSTADVICE"] as const;

const schema = z.object({
  id: z.string().optional(),
  author: z.string().min(1, "Author name is required.").max(80),
  role: z.string().max(120).optional(),
  body: z.string().min(1, "Review text is required.").max(2000),
  rating: z.coerce.number().int().min(1).max(5).default(5),
  source: z.enum(SOURCES).default("INTERNAL"),
  approved: z.boolean(),
  featured: z.boolean(),
});

function revalidate() {
  revalidatePath("/admin/reviews");
  revalidatePath("/"); // homepage badges + "what our customers say" section
}

/** Create or update a review. Wired to a <form> via useActionState. */
export async function saveReview(_prev: ActionState, formData: FormData): Promise<ActionState> {
  await requireArea("platform");

  const parsed = schema.safeParse({
    id: (formData.get("id") as string) || undefined,
    author: formData.get("author"),
    role: (formData.get("role") as string) || undefined,
    body: formData.get("body"),
    rating: formData.get("rating") ?? 5,
    source: (formData.get("source") as string) || "INTERNAL",
    approved: formData.get("approved") === "on" || formData.get("approved") === "true",
    featured: formData.get("featured") === "on" || formData.get("featured") === "true",
  });

  if (!parsed.success) {
    return { error: parsed.error.issues[0]?.message ?? "Invalid review." };
  }

  const { id, role, ...rest } = parsed.data;
  const data = { ...rest, role: role || null };

  try {
    if (id) {
      const existing = await db.review.findUnique({ where: { id } });
      if (!existing) return { error: "Review not found." };
      await db.review.update({ where: { id }, data });
    } else {
      await db.review.create({ data });
    }
  } catch (err) {
    await logEvent("error", "review.save", { message: String(err), author: data.author });
    return { error: "Could not save the review. Please try again." };
  }

  revalidate();
  return { ok: true };
}

/** Toggle whether a review is publicly shown. */
export async function toggleReviewApproved(id: string): Promise<ActionState> {
  await requireArea("platform");
  const r = await db.review.findUnique({ where: { id } });
  if (!r) return { error: "Review not found." };
  await db.review.update({ where: { id }, data: { approved: !r.approved } });
  revalidate();
  return { ok: true };
}

/** Toggle whether a review floats to the top of the display section. */
export async function toggleReviewFeatured(id: string): Promise<ActionState> {
  await requireArea("platform");
  const r = await db.review.findUnique({ where: { id } });
  if (!r) return { error: "Review not found." };
  await db.review.update({ where: { id }, data: { featured: !r.featured } });
  revalidate();
  return { ok: true };
}

/** Permanently delete a review. */
export async function deleteReview(id: string): Promise<ActionState> {
  await requireArea("platform");
  const r = await db.review.findUnique({ where: { id } });
  if (!r) return { error: "Review not found." };
  await db.review.delete({ where: { id } });
  revalidate();
  return { ok: true };
}

const urlSchema = z
  .string()
  .trim()
  .max(300)
  .refine((v) => v === "" || /^https?:\/\/.+/i.test(v), "Enter a full URL starting with https://");

/**
 * Save the external review-profile URLs (Trustpilot / HostAdvice / Google) via
 * the shared Setting store. These drive the homepage badge links and gate the
 * post-purchase review-request email — an empty value means "not set up".
 */
export async function saveReviewProfileUrls(_prev: ActionState, formData: FormData): Promise<ActionState> {
  await requireArea("platform");

  const entries: [string, unknown][] = [
    ["review_url_trustpilot", formData.get("review_url_trustpilot")],
    ["review_url_hostadvice", formData.get("review_url_hostadvice")],
    ["review_url_google", formData.get("review_url_google")],
  ];

  for (const [key, raw] of entries) {
    const parsed = urlSchema.safeParse(typeof raw === "string" ? raw : "");
    if (!parsed.success) return { error: `${key}: ${parsed.error.issues[0]?.message}` };
    await setSetting(key, parsed.data);
  }

  revalidate();
  return { ok: true };
}

