"use client";

import { useActionState, useEffect, useRef, useState, useTransition } from "react";
import {
  saveReview,
  toggleReviewApproved,
  toggleReviewFeatured,
  deleteReview,
  saveReviewProfileUrls,
} from "@/lib/actions-reviews";

type ReviewSource = "INTERNAL" | "GOOGLE" | "TRUSTPILOT" | "HOSTADVICE";

const SOURCES: ReviewSource[] = ["INTERNAL", "GOOGLE", "TRUSTPILOT", "HOSTADVICE"];

/** Add-a-review form. Resets on success. */
export function ReviewCreateForm() {
  const [state, action, pending] = useActionState(saveReview, {} as { error?: string; ok?: boolean });
  const formRef = useRef<HTMLFormElement>(null);

  useEffect(() => {
    if (state?.ok) formRef.current?.reset();
  }, [state]);

  return (
    <form ref={formRef} action={action} className="space-y-4">
      {state?.error && (
        <div className="rounded-lg border border-red-500/30 bg-red-500/10 px-3 py-2 text-sm text-red-400">
          {state.error}
        </div>
      )}
      {state?.ok && (
        <div className="rounded-lg border border-emerald-500/30 bg-emerald-500/10 px-3 py-2 text-sm text-emerald-300">
          Review saved.
        </div>
      )}

      <div className="grid gap-4 sm:grid-cols-2 lg:grid-cols-4">
        <div>
          <label className="label">Author</label>
          <input className="input" name="author" required maxLength={80} placeholder="Jane D." />
        </div>
        <div>
          <label className="label">Role / company (optional)</label>
          <input className="input" name="role" maxLength={120} placeholder="Game community host" />
        </div>
        <div>
          <label className="label">Source</label>
          <select className="input" name="source" defaultValue="INTERNAL">
            {SOURCES.map((s) => (
              <option key={s} value={s}>
                {s.charAt(0) + s.slice(1).toLowerCase()}
              </option>
            ))}
          </select>
        </div>
        <div>
          <label className="label">Rating (1–5)</label>
          <input className="input" name="rating" type="number" min={1} max={5} defaultValue={5} />
        </div>
      </div>

      <div>
        <label className="label">Review</label>
        <textarea
          className="input min-h-[90px]"
          name="body"
          required
          maxLength={2000}
          rows={3}
          placeholder="Nxeon had my modded Minecraft server live in under two minutes — full root, and it just worked."
        />
      </div>

      <div className="flex flex-wrap items-center justify-between gap-3 border-t border-white/[0.06] pt-4">
        <div className="flex flex-wrap items-center gap-5">
          <label className="flex items-center gap-2 text-sm text-slate-300">
            <input type="checkbox" name="approved" defaultChecked /> Approved (shown publicly)
          </label>
          <label className="flex items-center gap-2 text-sm text-slate-300">
            <input type="checkbox" name="featured" /> Featured (top of section)
          </label>
        </div>
        <button className="btn-primary" disabled={pending}>
          {pending ? "Saving…" : "Add review"}
        </button>
      </div>
    </form>
  );
}

/** Per-row approve / feature / delete controls. */
export function ReviewRowActions({
  id,
  approved,
  featured,
}: {
  id: string;
  approved: boolean;
  featured: boolean;
}) {
  const [pending, start] = useTransition();
  const [confirming, setConfirming] = useState(false);
  const [err, setErr] = useState<string | null>(null);

  const act = (fn: () => Promise<{ error?: string }>) =>
    start(async () => {
      setErr(null);
      const res = await fn();
      if (res.error) setErr(res.error);
    });

  return (
    <div className="flex items-center justify-end gap-2">
      {err && <span className="text-xs text-red-400">{err}</span>}
      <button
        className="btn-secondary px-3 py-1.5 text-xs"
        disabled={pending}
        onClick={() => act(() => toggleReviewApproved(id))}
      >
        {approved ? "Unapprove" : "Approve"}
      </button>
      <button
        className="btn-secondary px-3 py-1.5 text-xs"
        disabled={pending}
        onClick={() => act(() => toggleReviewFeatured(id))}
      >
        {featured ? "Unfeature" : "Feature"}
      </button>
      {confirming ? (
        <>
          <button
            className="btn-danger px-3 py-1.5 text-xs"
            disabled={pending}
            onClick={() =>
              act(async () => {
                const res = await deleteReview(id);
                if (res.error) setConfirming(false);
                return res;
              })
            }
          >
            {pending ? "Deleting…" : "Confirm"}
          </button>
          <button className="btn-ghost px-2 py-1.5 text-xs" disabled={pending} onClick={() => setConfirming(false)}>
            Cancel
          </button>
        </>
      ) : (
        <button className="btn-danger px-3 py-1.5 text-xs" onClick={() => setConfirming(true)}>
          Delete
        </button>
      )}
    </div>
  );
}

/** Settings form for the external review-profile URLs. */
export function ReviewProfileUrlsForm({
  trustpilot,
  hostadvice,
  google,
}: {
  trustpilot: string;
  hostadvice: string;
  google: string;
}) {
  const [state, action, pending] = useActionState(saveReviewProfileUrls, {} as { error?: string; ok?: boolean });

  return (
    <form action={action} className="space-y-4">
      {state?.error && (
        <div className="rounded-lg border border-red-500/30 bg-red-500/10 px-3 py-2 text-sm text-red-400">
          {state.error}
        </div>
      )}
      {state?.ok && (
        <div className="rounded-lg border border-emerald-500/30 bg-emerald-500/10 px-3 py-2 text-sm text-emerald-300">
          Review profile URLs saved.
        </div>
      )}
      <div className="grid gap-4 sm:grid-cols-3">
        <div>
          <label className="label">Trustpilot URL</label>
          <input className="input" name="review_url_trustpilot" defaultValue={trustpilot} placeholder="https://www.trustpilot.com/review/nxeon.cloud" />
        </div>
        <div>
          <label className="label">HostAdvice URL</label>
          <input className="input" name="review_url_hostadvice" defaultValue={hostadvice} placeholder="https://hostadvice.com/hosting-company/nxeon/" />
        </div>
        <div>
          <label className="label">Google reviews URL</label>
          <input className="input" name="review_url_google" defaultValue={google} placeholder="https://g.page/r/..." />
        </div>
      </div>
      <div className="flex justify-end">
        <button className="btn-primary" disabled={pending}>
          {pending ? "Saving…" : "Save profile URLs"}
        </button>
      </div>
      <p className="text-xs text-slate-500">
        Leave a field blank to hide that badge and skip it in the review-request email. The post-purchase
        email only sends when at least one URL is set.
      </p>
    </form>
  );
}

import { db } from "@/lib/db";
import { requireArea } from "@/lib/rbac";
import { getSetting } from "@/lib/settings";
import { PageHeader, Badge } from "@/components/ui/primitives";
import {
  ReviewCreateForm,
  ReviewRowActions,
  ReviewProfileUrlsForm,
} from "@/components/admin/ReviewControls";

export const dynamic = "force-dynamic";

function Stars({ rating }: { rating: number }) {
  const n = Math.max(0, Math.min(5, rating));
  return (
    <span className="whitespace-nowrap text-sm" aria-label={`${n} of 5`}>
      <span className="text-amber-400">{"★".repeat(n)}</span>
      <span className="text-slate-700">{"★".repeat(5 - n)}</span>
    </span>
  );
}

const SOURCE_LABEL: Record<string, string> = {
  INTERNAL: "Internal",
  GOOGLE: "Google",
  TRUSTPILOT: "Trustpilot",
  HOSTADVICE: "HostAdvice",
};

export default async function AdminReviews() {
  await requireArea("platform");

  const [reviews, trustpilot, hostadvice, google] = await Promise.all([
    db.review.findMany({ orderBy: [{ featured: "desc" }, { createdAt: "desc" }] }),
    getSetting("review_url_trustpilot"),
    getSetting("review_url_hostadvice"),
    getSetting("review_url_google"),
  ]);

  const approved = reviews.filter((r) => r.approved).length;

  return (
    <div className="space-y-6">
      <PageHeader
        title="Reviews"
        sub="Real customer reviews. Approved reviews power the homepage badges and the “What our customers say” section; until any exist, the badges show the clearly-labelled demo placeholder."
      />

      <div className="card">
        <p className="section-label mb-4">External review profiles</p>
        <ReviewProfileUrlsForm trustpilot={trustpilot} hostadvice={hostadvice} google={google} />
      </div>

      <div className="card">
        <p className="section-label mb-4">Add a review</p>
        <ReviewCreateForm />
      </div>

      <div className="card overflow-x-auto p-0">
        <div className="flex items-center justify-between px-4 pt-4">
