import { db } from "./db";
import { getSetting } from "./settings";
import { emails, sendMail } from "./mailer";

/**
 * Post-purchase review request. Sent exactly once per server, the first time it
 * goes ACTIVE (worker provision success), thanking the customer and asking for an
 * honest review that links our configured external profiles.
 *
 * Idempotent and defensive by design:
 *   - `Server.reviewRequestSentAt` guards against a retried PROVISION job sending
 *     twice — we only mark it AFTER a successful send.
 *   - If no external profile URL is configured, we skip silently: never ask a
 *     customer to "leave a review" with nowhere to send them.
 *   - The mail goes through `sendMail` with `kind: "product_news"`, so a customer
 *     who opted out of product/marketing email is respected centrally.
 *   - Never throws — a failed review email must not fail provisioning.
 */
export async function sendReviewRequestForServer(serverId: string): Promise<void> {
  try {
    const server = await db.server.findUnique({
      where: { id: serverId },
      select: {
        id: true,
        hostname: true,
        reviewRequestSentAt: true,
        userId: true,
        user: { select: { email: true, name: true } },
      },
    });
    if (!server || server.reviewRequestSentAt) return;
    if (!server.user?.email) return;

    const [trustpilot, hostadvice, google] = await Promise.all([
      getSetting("review_url_trustpilot"),
      getSetting("review_url_hostadvice"),
      getSetting("review_url_google"),
    ]);
    const profiles = [
      { label: "Trustpilot", url: trustpilot.trim() },
      { label: "HostAdvice", url: hostadvice.trim() },
      { label: "Google", url: google.trim() },
    ].filter((p) => p.url.length > 0);

    if (profiles.length === 0) return; // no profiles configured — skip gracefully

    const em = emails.reviewRequest({ name: server.user.name, hostname: server.hostname, profiles });
    const sent = await sendMail({
      to: server.user.email,
      subject: em.subject,
      html: em.html,
      userId: server.userId,
      kind: "product_news",
    });

    if (sent) {
      await db.server.update({ where: { id: server.id }, data: { reviewRequestSentAt: new Date() } });
    }
  } catch (e) {
    console.error("[review-request] failed to send for server", serverId, e);
  }
}

